"<!DOCTYPE html>
<html lang=\"pt-br\">
<head>
<meta charset=\"UTF-8\">
<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, user-scalable=no\">
<title>Pula @COMMENT_BODY@ Coleta - Jogo 2D</title>
<style>
  *{margin:0;padding:0;box-sizing:border-box}
  body{background:#111;display:flex;flex-direction:column;align-items:center;justify-content:center;height:100vh;font-family:Arial;color:white;overflow:hidden}
  h1{font-size:20px;margin-bottom:5px}
  #placar{font-size:16px;margin-bottom:8px}
  canvas{background:linear-gradient(#87CEEB,#fff);border:3px solid white;border-radius:10px;max-width:95vw}
  .botoes{display:flex;gap:10px;margin-top:10px}
  button{padding:15px 25px;font-size:18px;border:none;border-radius:10px;background:#ff4757;color:white;font-weight:bold}
  button:active{transform:scale(0.95)}
  #pular{background:#2ed573}
</style>
</head>
<body>
<h1>🕹️ PULA @COMMENT_BODY@ COLETA</h1>
<div id=\"placar\">Moedas: 0 | Recorde: 0</div>
<canvas id=\"game\" width=\"360\" height=\"400\"></canvas>
<div class=\"botoes\">
  <button onclick=\"mover(-1)\">◀️</button>
  <button id=\"pular\" onclick=\"pular()\">PULAR ⬆️</button>
  <button onclick=\"mover(1)\">▶️</button>
</div>
<p style=\"margin-top:8px;font-size:12px;opacity:0.7\">No PC usa ← → e ESPAÇO</p>

<script>
const canvas=document.getElementById('game');
const ctx=canvas.getContext('2d');
let jogador={x:50,y:300,w:30,h:30,vy:0,pulando:false,cor:'#ff4757'};
let gravidade=0.6, chao=350;
let moedas=[], espinhos=[], pontos=0, recorde=localStorage.getItem('recorde')||0;
let gameOver=false;

function criarMoeda(){ moedas.push({x:360,y:Math.random()*200+80,r:12}); }
function criarEspinho(){ espinhos.push({x:360,y:chao,w:25,h:25}); }
setInterval(()=>{ if(!gameOver) criarMoeda(); },1500);
setInterval(()=>{ if(!gameOver) criarEspinho(); },1200);

function mover(dir){ jogador.x+=dir*20; if(jogador.x<0) jogador.x=0; if(jogador.x>330) jogador.x=330; }
function pular(){ if(!jogador.pulando){ jogador.vy=-12; jogador.pulando=true; } }

document.addEventListener('keydown',e=>{
  if(e.key==='ArrowLeft') mover(-1);
  if(e.key==='ArrowRight') mover(1);
  if(e.key===' ') pular();
});

function desenhar(){
  ctx.clearRect(0,0,360,400);
  // chão
  ctx.fillStyle='#2ed573'; ctx.fillRect(0,chao+30,360,50);
  // jogador
  ctx.fillStyle=jogador.cor;
  ctx.fillRect(jogador.x,jogador.y,jogador.w,jogador.h);
  ctx.fillStyle='white'; ctx.fillRect(jogador.x+6,jogador.y+6,6,6); ctx.fillRect(jogador.x+18,jogador.y+6,6,6);
  // moedas
  ctx.fillStyle='gold';
  moedas.forEach(m=>{ ctx.beginPath(); ctx.arc(m.x,m.y,m.r,0,Math.PI*2); ctx.fill(); });
  // espinhos
  ctx.fillStyle='#333';
  espinhos.forEach(e=>{ ctx.beginPath(); ctx.moveTo(e.x,e.y+e.h); ctx.lineTo(e.x+e.w/2,e.y); ctx.lineTo(e.x+e.w,e.y+e.h); ctx.fill(); });
  if(gameOver){ ctx.fillStyle='rgba(0,0,0,0.7)'; ctx.fillRect(0,0,360,400); ctx.fillStyle='white'; ctx.font='bold 24px Arial'; ctx.textAlign='center'; ctx.fillText('GAME OVER',180,180); ctx.font='16px Arial'; ctx.fillText('Toque pra jogar de novo',180,210); }
}

function atualizar(){
  if(gameOver) return;
  jogador.vy+=gravidade; jogador.y+=jogador.vy;
  if(jogador.y>=chao){ jogador.y=chao; jogador.vy=0; jogador.pulando=false; }
  moedas.forEach((m,i)=>{ m.x-=2; if(Math.abs(m.x-jogador.x)<25 @COMMENT_BODY@@COMMENT_BODY@ Math.abs(m.y-jogador.y)<25){ moedas.splice(i,1); pontos++; document.getElementById('placar').innerText=`Moedas: ${pontos} | Recorde: ${recorde}`; } });
  espinhos.forEach((e,i)=>{ e.x-=3; if(jogador.x<e.x+e.w @COMMENT_BODY@@COMMENT_BODY@ jogador.x+jogador.w>e.x @COMMENT_BODY@@COMMENT_BODY@ jogador.y+jogador.h>e.y){ gameOver=true; if(pontos>recorde){ recorde=pontos; localStorage.setItem('recorde',recorde); } } });
  moedas=moedas.filter(m=>m.x>-20); espinhos=espinhos.filter(e=>e.x>-30);
}

canvas.addEventListener('click',()=>{ if(gameOver){ gameOver=false; pontos=0; moedas=[]; espinhos=[]; jogador.x=50; jogador.y=300; } });

setInterval(()=>{ atualizar(); desenhar(); },1000/60);
document.getElementById('placar').innerText=`Moedas: 0 | Recorde: ${recorde}`;
</script>
</body>
</html>

---
